import{f as r,c as t,o as e,a5 as s}from"./chunks/framework.BsEAYNxL.js";const p=JSON.parse('{"title":"AI 编年史 03：架构演进 (Architecture) 的王者之路","description":"","frontmatter":{"title":"AI 编年史 03：架构演进 (Architecture) 的王者之路","date":"2026-02-14T00:00:00.000Z","categories":["AI","Tech History"],"tags":["Transformer","RNN","LSTM","MoE","SSM","Mamba","Chronicle"],"ai_role":"writer","reading_stats":{"count":919,"minutes":3}},"headers":[],"relativePath":"ai-chronicles/04-architecture.md","filePath":"ai-chronicles/04-architecture.md","lastUpdated":null}'),n={name:"ai-chronicles/04-architecture.md"};function o(l,a,i,h,m,c){return e(),t("div",null,[...a[0]||(a[0]=[s('<h2 id="第一阶段-分治时代-——-各自为政-pre-2017" tabindex="-1">第一阶段：分治时代 —— 各自为政 (Pre-2017) <a class="header-anchor" href="#第一阶段-分治时代-——-各自为政-pre-2017" aria-label="Permalink to &quot;第一阶段：分治时代 —— 各自为政 (Pre-2017)&quot;">​</a></h2><p>在 Transformer 之前，不同领域使用完全不同的模型架构。</p><h3 id="_1-1-nlp-领域的-rnn-lstm" tabindex="-1">1.1 NLP 领域的 RNN/LSTM <a class="header-anchor" href="#_1-1-nlp-领域的-rnn-lstm" aria-label="Permalink to &quot;1.1 NLP 领域的 RNN/LSTM&quot;">​</a></h3><ul><li><strong>架构特点</strong>：循环神经网络 (Recurrent Neural Network)。处理序列数据，像人阅读一样逐词扫描。</li><li><strong>局限性</strong>：无法并行训练（慢），长距离依赖丢失（忘）。</li><li><strong>代表</strong>：<strong><a href="https://www.bioinf.jku.at/publications/older/2604.pdf" target="_blank" rel="noreferrer">LSTM (Long Short-Term Memory, 1997)</a></strong>, GRU。</li></ul><h3 id="_1-2-cv-领域的-cnn" tabindex="-1">1.2 CV 领域的 CNN <a class="header-anchor" href="#_1-2-cv-领域的-cnn" aria-label="Permalink to &quot;1.2 CV 领域的 CNN&quot;">​</a></h3><ul><li><strong>架构特点</strong>：卷积神经网络 (Convolutional Neural Network)。通过滑窗提取局部特征，具有平移不变性。</li><li><strong>局限性</strong>：感受野受限，难以捕捉全局关系（虽然堆深层可以缓解，但不够直接）。</li><li><strong>代表</strong>：<strong><a href="https://arxiv.org/abs/1512.03385" target="_blank" rel="noreferrer">ResNet (2015)</a></strong>, VGG, Inception。</li></ul><h2 id="第二阶段-transformer-的大一统-——-attention-is-all-you-need-2017-2020" tabindex="-1">第二阶段：Transformer 的大一统 —— Attention Is All You Need (2017 - 2020) <a class="header-anchor" href="#第二阶段-transformer-的大一统-——-attention-is-all-you-need-2017-2020" aria-label="Permalink to &quot;第二阶段：Transformer 的大一统 —— Attention Is All You Need (2017 - 2020)&quot;">​</a></h2><p>Google 的神作 <strong><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer"><em>Attention Is All You Need</em> (2017)</a></strong> 改变了一切。</p><h3 id="_2-1-核心思想" tabindex="-1">2.1 核心思想 <a class="header-anchor" href="#_2-1-核心思想" aria-label="Permalink to &quot;2.1 核心思想&quot;">​</a></h3><ul><li><strong>Self-Attention</strong>：每个词都能直接看到句子里的其他所有词，无论距离多远。</li><li><strong>并行计算</strong>：抛弃了循环，所有词可以同时输入 GPU 计算。效率提升百倍。</li><li><strong>位置编码</strong>：既然没有循环，就需要显式告诉模型每个词的位置。</li></ul><h3 id="_2-2-bert-与-gpt-的路线之争-2018" tabindex="-1">2.2 BERT 与 GPT 的路线之争 (2018) <a class="header-anchor" href="#_2-2-bert-与-gpt-的路线之争-2018" aria-label="Permalink to &quot;2.2 BERT 与 GPT 的路线之争 (2018)&quot;">​</a></h3><p>Transformer 架构随后分裂为两大流派：</p><ol><li><strong>Encoder-only (</strong><a href="https://arxiv.org/abs/1810.04805" target="_blank" rel="noreferrer">BERT, 2018</a><strong>)</strong>：双向理解，擅长完形填空、分类、情感分析。Google 阵营。</li><li><strong>Decoder-only (</strong><a href="https://cdn.openai.com/research-covers/language-unsupervised/language_understanding_paper.pdf" target="_blank" rel="noreferrer">GPT-1, 2018</a><strong>)</strong>：单向生成，擅长接龙、创作。OpenAI 阵营。 <ul><li><strong>历史转折点</strong>：当时 BERT 效果更好，横扫 NLP 榜单。但 OpenAI 坚信“生成”才是通往 AGI 的路，死磕 GPT。事实证明他们赌对了。</li></ul></li></ol><h3 id="_2-3-vit-vision-transformer-2020" tabindex="-1">2.3 ViT (Vision Transformer, 2020) <a class="header-anchor" href="#_2-3-vit-vision-transformer-2020" aria-label="Permalink to &quot;2.3 ViT (Vision Transformer, 2020)&quot;">​</a></h3><ul><li><strong>突破</strong>：Google 将图片切成 16x16 的小块 (Patch)，当作“单词”喂给 <strong><a href="https://arxiv.org/abs/2010.11929" target="_blank" rel="noreferrer">ViT (Vision Transformer, 2020)</a></strong>。</li><li><strong>意义</strong>：证明了 Transformer 不仅能处理文字，也能处理图片。CV 领域的 CNN 霸主地位开始动摇。</li></ul><h2 id="第三阶段-moe-mixture-of-experts-——-大而不当的解药-2021-2023" tabindex="-1">第三阶段：MoE (Mixture of Experts) —— 大而不当的解药 (2021 - 2023) <a class="header-anchor" href="#第三阶段-moe-mixture-of-experts-——-大而不当的解药-2021-2023" aria-label="Permalink to &quot;第三阶段：MoE (Mixture of Experts) —— 大而不当的解药 (2021 - 2023)&quot;">​</a></h2><p>随着 Scaling Law 生效，模型参数量指数级增长。训练和推理成本变得不可接受。</p><h3 id="_3-1-背景与痛点" tabindex="-1">3.1 背景与痛点 <a class="header-anchor" href="#_3-1-背景与痛点" aria-label="Permalink to &quot;3.1 背景与痛点&quot;">​</a></h3><ul><li><strong>稠密模型 (Dense Model)</strong>：GPT-3 有 1750 亿参数。每次推理，这 1750 亿个参数都要参与计算。哪怕只是问“1+1等于几”。</li><li><strong>成本墙</strong>：计算量太大，显存带宽不够。</li></ul><h3 id="_3-2-解决方案-moe-混合专家模型" tabindex="-1">3.2 解决方案：MoE (混合专家模型) <a class="header-anchor" href="#_3-2-解决方案-moe-混合专家模型" aria-label="Permalink to &quot;3.2 解决方案：MoE (混合专家模型)&quot;">​</a></h3><ul><li><strong>原理</strong>： <ul><li>把大模型拆成很多个小专家 (Experts)，比如 8 个甚至 64 个。</li><li>引入一个 <strong>Router (门控网络)</strong>，根据输入决定把任务派给哪几个专家。</li><li><strong>稀疏激活 (Sparse Activation)</strong>：每次推理只激活一小部分参数（比如 1/8）。</li></ul></li><li><strong>代表模型</strong>： <ul><li><strong><a href="https://arxiv.org/abs/2101.03961" target="_blank" rel="noreferrer">Switch Transformer (Google, 2021)</a></strong>：万亿参数，但计算量很小。</li><li><strong>GPT-4</strong>：据传是 8x220B 的 MoE 架构。</li><li><strong><a href="https://arxiv.org/abs/2401.04088" target="_blank" rel="noreferrer">Mixtral 8x7B (2024)</a></strong>：开源界的高性能 MoE，效果吊打 Llama 2 70B。</li></ul></li></ul><h2 id="第四阶段-线性注意力与-ssm-——-挑战-transformer-2023-2024" tabindex="-1">第四阶段：线性注意力与 SSM —— 挑战 Transformer (2023 - 2024) <a class="header-anchor" href="#第四阶段-线性注意力与-ssm-——-挑战-transformer-2023-2024" aria-label="Permalink to &quot;第四阶段：线性注意力与 SSM —— 挑战 Transformer (2023 - 2024)&quot;">​</a></h2><p>Transformer 的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>O</mi><mo stretchy="false">(</mo><msup><mi>N</mi><mn>2</mn></msup><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">O(N^2)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.10903em;">N</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 复杂度始终是处理超长序列的痛。</p><h3 id="_4-1-背景与痛点" tabindex="-1">4.1 背景与痛点 <a class="header-anchor" href="#_4-1-背景与痛点" aria-label="Permalink to &quot;4.1 背景与痛点&quot;">​</a></h3><ul><li><strong>计算复杂度</strong>：序列长度翻倍，计算量翻 4 倍。处理百万级上下文极其昂贵。</li><li><strong>推理显存</strong>：KV Cache 占用大量显存。</li></ul><h3 id="_4-2-挑战者-ssm-state-space-models" tabindex="-1">4.2 挑战者：SSM (State Space Models) <a class="header-anchor" href="#_4-2-挑战者-ssm-state-space-models" aria-label="Permalink to &quot;4.2 挑战者：SSM (State Space Models)&quot;">​</a></h3><ul><li><strong><a href="https://arxiv.org/abs/2312.00752" target="_blank" rel="noreferrer">Mamba (2023)</a></strong>：基于 SSM 架构。 <ul><li><strong>优势</strong>：推理复杂度是线性的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>O</mi><mo stretchy="false">(</mo><mi>N</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">O(N)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.10903em;">N</span><span class="mclose">)</span></span></span></span>。推理时只需要更新一个很小的隐状态，不需要存 KV Cache。</li><li><strong>效果</strong>：在长序列任务上表现优异，推理速度极快。</li></ul></li><li><strong><a href="https://arxiv.org/abs/2305.13048" target="_blank" rel="noreferrer">RWKV (2023)</a></strong>：RNN 的复兴。结合了 Transformer 的并行训练优势和 RNN 的线性推理优势。</li></ul><h3 id="_4-3-现状" tabindex="-1">4.3 现状 <a class="header-anchor" href="#_4-3-现状" aria-label="Permalink to &quot;4.3 现状&quot;">​</a></h3><p>虽然 SSM 在某些领域表现出色，但在通用能力和生态上，Transformer (及其 MoE 变体) 依然是绝对的王者。但架构的演进从未停止。</p>',29)])])}const u=r(n,[["render",o]]);export{p as __pageData,u as default};
